import { createRequire } from "node:module";

// Generated by `prisma generate --schema prisma/tenant/schema.prisma`.
const require = createRequire(import.meta.url);
const { PrismaClient, Prisma } = require("../../node_modules/.prisma/tenant-client/index.js");

/**
 * One PrismaClient per client database (nubred_{slug}). Created on first use
 * and cached. The tenant schema lives in prisma/tenant/schema.prisma.
 */

/** Prisma namespace of the tenant client (JsonNull, error classes, ...). */
export const TenantPrisma = Prisma;

const clients = new Map();

/**
 * Base connection string used to reach client databases. Same Postgres
 * instance as the platform database unless NUBRED_TENANT_DATABASE_URL is set.
 */
function baseUrl() {
  const url = process.env.NUBRED_TENANT_DATABASE_URL || process.env.DATABASE_URL;
  if (!url) {
    throw new Error(
      "NUBRED_TENANT_DATABASE_URL (or DATABASE_URL) is not set; cannot reach client databases."
    );
  }
  return url;
}

/**
 * Connection string for one client database.
 * @param {string} databaseName
 * @param {{ connectionLimit?: number }} [options]
 */
export function tenantDatabaseUrl(databaseName, options = {}) {
  const url = new URL(baseUrl());
  url.pathname = `/${databaseName}`;
  const limit =
    options.connectionLimit ??
    Number.parseInt(process.env.NUBRED_TENANT_DB_CONNECTION_LIMIT ?? "", 10);
  if (Number.isFinite(limit) && limit > 0) {
    url.searchParams.set("connection_limit", String(limit));
  } else if (!url.searchParams.has("connection_limit")) {
    url.searchParams.set("connection_limit", "5");
  }
  return url.toString();
}

/**
 * Database names are derived from a validated slug; refuse anything else
 * before it reaches a connection string or CREATE DATABASE.
 */
const DATABASE_NAME = /^nubred_[a-z0-9_]{1,56}$/;

export function assertDatabaseName(name) {
  if (typeof name !== "string" || !DATABASE_NAME.test(name)) {
    throw new Error(`Invalid tenant database name "${name}".`);
  }
  return name;
}

/**
 * @param {{ databaseName: string }} tenant
 * @returns {PrismaClient}
 */
export function getTenantDb(tenant) {
  const name = assertDatabaseName(tenant.databaseName);
  let client = clients.get(name);
  if (!client) {
    client = new PrismaClient({
      datasources: { db: { url: tenantDatabaseUrl(name) } },
    });
    clients.set(name, client);
  }
  return client;
}

/** Disconnect and forget a cached client (before dropping its database). */
export async function evictTenantDb(databaseName) {
  const client = clients.get(databaseName);
  if (!client) return;
  clients.delete(databaseName);
  await client.$disconnect().catch(() => {});
}

/** For tests. */
export async function disconnectAllTenantDbs() {
  await Promise.all(
    [...clients.keys()].map((name) => evictTenantDb(name))
  );
}
